/**
 * Renders an InputSpec into ORCA input text.
 *
 * This is the browser twin of `inputbuild.Input.Render` in the wrapper;
 * the layout below is the same contract, down to the coordinate column
 * widths, so a job built here and a job generated by the CLI are
 * indistinguishable:
 *
 *     ! KEYWORD KEYWORD …
 *     %pal nprocs N end          (omitted when 0)
 *     %maxcore M                 (omitted when 0)
 *     <blocks>
 *     * xyz CHARGE MULT          | * xyzfile CHARGE MULT file.xyz
 *     El   x   y   z
 *     *
 */
import type { Atom, InputSpec, Resources } from "./types";

/** Fixed-point column layout of one coordinate row, matching the Go renderer. */
export function atomLine(atom: Atom): string {
  const el = atom.el.padEnd(3, " ");
  return `${el} ${fixed(atom.x)} ${fixed(atom.y)} ${fixed(atom.z)}\n`;
}

function fixed(v: number): string {
  // %14.8f — 8 decimals, right-aligned in 14 columns. Non-finite values
  // would render as "NaN" and produce an input ORCA aborts on, so they
  // are pinned to 0 here and reported by the linter instead.
  const n = Number.isFinite(v) ? v : 0;
  return n.toFixed(8).padStart(14, " ");
}

export function renderResources(res: Resources): string {
  let out = "";
  if (res.nprocs > 0) out += `%pal nprocs ${res.nprocs} end\n`;
  if (res.maxCoreMB > 0) out += `%maxcore ${res.maxCoreMB}\n`;
  return out;
}

/** A standalone .xyz file (count + comment + atoms). */
export function renderXYZFile(comment: string, atoms: Atom[]): string {
  return `${atoms.length}\n${comment}\n${atoms.map(atomLine).join("")}`;
}

export function renderInput(spec: InputSpec): string {
  let out = `! ${spec.keywords.join(" ")}\n`;
  out += renderResources(spec.res);
  for (const block of spec.blocks) {
    const text = block.trimEnd();
    if (!text) continue;
    out += `${text}\n`;
  }
  const { charge, multiplicity } = spec.env;
  if (spec.xyzFileName) {
    out += `* xyzfile ${charge} ${multiplicity} ${spec.xyzFileName}\n`;
    return out;
  }
  if (spec.structure) {
    out += `* xyz ${charge} ${multiplicity}\n`;
    out += spec.structure.atoms.map(atomLine).join("");
    out += "*\n";
  }
  return out;
}
